effect.shader:
vec2 hash2(vec2 p) {
    p = vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)));
    return fract(sin(p) * 43758.5453);
}

void main() {
    vec2 uv = acScreenNorm;
    vec2 px = uv * acResolution;
    vec2 blockId = floor(px / blockSize);
    float tSlot = floor(acTime * speed * 4.0) / 4.0;
    vec2 h = hash2(blockId + tSlot);
    float ativo = step(1.0 - amount, h.x);

    vec2 shift = (h - 0.5) * amount * 0.12 * ativo;
    vec2 uvS = uv + shift;

    float rShift = channelShift * amount * 0.02 * ativo;
    float r = texture(inputImg, uvS + vec2(rShift, 0.0)).r;
    vec4 g = texture(inputImg, uvS);
    float b = texture(inputImg, uvS - vec2(rShift, 0.0)).b;

    fragColor = vec4(r, g.g, b, g.a);
}
